class Customer extends Account {
  calculateDiscount(order: Order) {
    const base = order.items.reduce((s, i) => s + i.price, 0);
    return base > 100 ? base * 0.1 : 0;
  }
}
class Supplier extends Account {
  calculateDiscount(order: Order) {
    const base = order.items.reduce((s, i) => s + i.price, 0);
    return base > 100 ? base * 0.1 : 0;
  }
}

class OnlineOrder extends Order {
  computeTotal() {
    const sum = this.items.reduce((s, i) => s + i.price, 0);
    return Math.round(sum * 100) / 100; // rounds to cents
  }
}
class InStoreOrder extends Order {
  computeTotal() {
    const sum = this.items.reduce((s, i) => s + i.price, 0);
    return sum; // no rounding here
  }
}

/* Version A */
class Order {
  total() {
    const base = this.items.reduce((s, i) => s + i.price, 0);
    return this.applyAdjustments(base);
  }
  protected applyAdjustments(amount: number) { return amount; }
}
class OnlineOrder extends Order { protected applyAdjustments(a: number) { return Math.round(a * 100) / 100; } }
class InStoreOrder extends Order { protected applyAdjustments(a: number) { return a; } }

/* Version B */
function calculateTotal(order: Order, source: 'online' | 'instore') {
  const base = order.items.reduce((s, i) => s + i.price, 0);
  if (source === 'online') return Math.round(base * 100) / 100;
  return base;
}
